/** The keychain item Claude Code reads its login from, with its default config directory. */
export const LIVE_SERVICE = 'Claude Code-credentials'

/** The environment variables that decide where Claude Code keeps its login. */
export type StorageVariables = { configDir?: string; secureStorageDir?: string }

/**
 * The keychain service Claude Code keeps its login under, named as it names
 * it: `Claude Code-credentials`, then `-` and the first eight hex digits of
 * the SHA-256 of a folder when `CLAUDE_SECURESTORAGE_CONFIG_DIR` names one,
 * or else when `CLAUDE_CONFIG_DIR` is set (that folder, as given, NFC). An
 * empty `CLAUDE_SECURESTORAGE_CONFIG_DIR` keeps the plain name.
 */
export async function liveServiceName(variables: StorageVariables, defaultConfigDir: string): Promise<string> {
  const { secureStorageDir, configDir } = variables
  const isPlain = secureStorageDir !== undefined ? secureStorageDir === '' : !configDir
  if (isPlain) return LIVE_SERVICE
  const folder = (secureStorageDir ?? configDir ?? defaultConfigDir).normalize('NFC')
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(folder))
  const hex = Array.from(new Uint8Array(digest), byte => byte.toString(16).padStart(2, '0')).join('')

  return `${LIVE_SERVICE}-${hex.slice(0, 8)}`
}

/** The folder Claude Code keeps `.credentials.json` in: `CLAUDE_SECURESTORAGE_CONFIG_DIR` when set (empty means the default), else its config directory. */
export function credentialsDirectory(variables: StorageVariables, defaultConfigDir: string): string {
  if (variables.secureStorageDir !== undefined) return (variables.secureStorageDir || defaultConfigDir).normalize('NFC')

  return (variables.configDir || defaultConfigDir).normalize('NFC')
}

/** The keychain account Claude Code reads its login with: the user's name, or `claude-code-user` when that holds other characters. */
export function keychainAccountName(user: string | undefined): string {
  return user && /^[a-zA-Z0-9._-]+$/.test(user) ? user : 'claude-code-user'
}
/** The keychain service this mod keeps one item per saved account under. */
export const VAULT_SERVICE = 'account-switch'
/** `security`'s exit code for an item that is not there. */
export const ITEM_NOT_FOUND = 44

/** The OAuth credential document Claude Code stores, kept whole. */
export type Credential = {
  claudeAiOauth: {
    accessToken: string
    refreshToken: string
    expiresAt: number
    scopes?: string[]
    subscriptionType?: string
    rateLimitTier?: string
    [field: string]: unknown
  }
  [field: string]: unknown
}

export class KeychainError extends Error {}

/**
 * Whether an account id is one this mod files a login under: letters, digits,
 * `-` and `_`, as a UUID is. It names a keychain item and a vault file, and
 * travels inside a `security -i` line, so nothing else may reach those.
 */
export function isAccountId(id: unknown): id is string {
  return typeof id === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(id)
}

function toHex(text: string): string {
  return Array.from(new TextEncoder().encode(text), byte => byte.toString(16).padStart(2, '0')).join('')
}

export function parseCredential(text: string): Credential {
  const parsed: unknown = JSON.parse(text.trim())
  const oauth = (parsed as Credential | null)?.claudeAiOauth
  if (typeof oauth?.accessToken !== 'string' || typeof oauth.refreshToken !== 'string') {
    throw new KeychainError('keychain item holds no Claude OAuth credential')
  }

  return parsed as Credential
}

/** argv printing one item's secret. */
export function findArgv(service: string, account?: string): string[] {
  return ['security', 'find-generic-password', '-s', service, ...(account ? ['-a', account] : []), '-w']
}

/**
 * The `security -i` line that creates or replaces an item. The secret travels
 * on stdin as hex, never in argv, the way Claude Code writes its own item.
 */
export function addLine(service: string, account: string, text: string): string {
  // `security -i` reads the line as a command line of its own: a quote, a backslash or a line break would end it.
  for (const value of [service, account]) {
    if (/["\\\n\r]/.test(value)) throw new KeychainError(`refused a keychain name with a quote, backslash or line break: ${JSON.stringify(value)}`)
  }

  return `add-generic-password -U -a "${account}" -s "${service}" -X "${toHex(text)}"\n`
}

export function deleteArgv(service: string, account: string): string[] {
  return ['security', 'delete-generic-password', '-s', service, '-a', account]
}

/**
 * Whether a login is an older copy than the one saved for its account: another
 * grant (refresh token) that expires sooner. Filing it would replace a newer
 * grant with one whose refresh token may already be spent.
 */
export function isOlderGrant(candidate: Credential, saved: Credential | null): boolean {
  if (saved === null) return false

  return candidate.claudeAiOauth.refreshToken !== saved.claudeAiOauth.refreshToken && candidate.claudeAiOauth.expiresAt < saved.claudeAiOauth.expiresAt
}

/** Whether two logins are one grant: the same refresh token, whatever access token each holds now. */
export function isSameGrant(a: Credential | null, b: Credential | null): boolean {
  return a !== null && b !== null && a.claudeAiOauth.refreshToken === b.claudeAiOauth.refreshToken
}

/**
 * Whether `.credentials.json` holds an older login than the keychain: another
 * token there, expiring no later. Claude Code refreshes into the keychain
 * alone, while a session with that file drops its cached login only when the
 * file changes, so a file left behind keeps every other session on a token
 * whose refresh token is already spent, and it expires with "Login expired".
 */
export function fileLagsKeychain(file: Credential | null, keychain: Credential): boolean {
  if (file === null) return false

  return file.claudeAiOauth.accessToken !== keychain.claudeAiOauth.accessToken && file.claudeAiOauth.expiresAt <= keychain.claudeAiOauth.expiresAt
}

files.hooks/lock.ts:
import type { Io } from './io'
import { encodePowerShell, powerShellLiteral } from './shared/files'

/**
 * Locks held across processes, laid out as proper-lockfile (Claude Code's own
 * locks) lays them: a directory that only one process can make, taken as
 * abandoned once its modification time is older than the lock's stale time.
 * Taking Claude Code's lock before writing a file it guards keeps the write
 * from landing between its read and its write.
 */

/** A lock this process holds. */
export type Lock = {
  /** Gives the lock up; a lock already taken over as stale is left alone. */
  release: () => Promise<void>
  /** Marks the lock alive, for work that holds it longer than half its stale time. */
  touch: () => Promise<void>
}

export class LockBusyError extends Error {}

export type LockOptions = {
  /** How old the lock's time may grow before another process takes it as abandoned. */
  staleMs: number
  /** How many times to try before giving up, waiting longer each time. */
  tries: number
  isWindows: boolean
}

/** The waits between tries: 100 ms, doubling, at most a second. */
export function retryDelay(attempt: number): number {
  return Math.min(1000, 100 * 2 ** attempt)
}

/** argv making the lock directory, its parent first; it fails when the directory is there. */
export function makeLockArgv(path: string, isWindows: boolean): string[] {
  if (!isWindows) return ['/bin/sh', '-c', 'mkdir -p "$(dirname "$0")" && mkdir "$0"', path]
  const script = `$p = ${powerShellLiteral(path)}; if (Test-Path -LiteralPath $p) { exit 1 }; New-Item -ItemType Directory -Force -Path (Split-Path -LiteralPath $p) | Out-Null; try { New-Item -ItemType Directory -Path $p -ErrorAction Stop | Out-Null } catch { exit 1 }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** argv removing the lock directory, empty as a lock is; absent is fine. */
export function removeLockArgv(path: string, isWindows: boolean): string[] {
  if (!isWindows) return ['/bin/sh', '-c', '[ ! -d "$0" ] || rmdir "$0"', path]
  const script = `$p = ${powerShellLiteral(path)}; if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Force -ErrorAction Stop }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** argv setting the lock directory's time to now. */
export function touchLockArgv(path: string, isWindows: boolean): string[] {
  if (!isWindows) return ['touch', path]
  const script = `(Get-Item -LiteralPath ${powerShellLiteral(path)}).LastWriteTime = Get-Date`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** Takes the lock at `path`, taking over one abandoned past its stale time; `LockBusyError` when it stays held. */
export async function acquire(io: Io, path: string, options: LockOptions): Promise<Lock> {
  for (let attempt = 0; attempt < options.tries; attempt += 1) {
    const made = await io.run(makeLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
    if (made.exitCode === 0) {
      let mtimeMs = (await io.stat(path).catch(() => null))?.mtimeMs ?? 0

      return {
        release: async () => {
          // Taken over as stale and made again by another process: that lock is not this one's to remove.
          const now = (await io.stat(path).catch(() => null))?.mtimeMs
          if (now === undefined || now !== mtimeMs) return
          await io.run(removeLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
        },
        touch: async () => {
          await io.run(touchLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
          mtimeMs = (await io.stat(path).catch(() => null))?.mtimeMs ?? mtimeMs
        },
      }
    }
    const held = await io.stat(path).catch(() => null)
    // Made by nobody yet the directory could not be made: not a lock held but a failure to report.
    if (held === null) throw new Error(`cannot make the lock ${path}: ${made.stderr.trim()}`)
    if ((await io.now()) - held.mtimeMs > options.staleMs) {
      // Removed only while it is still the abandoned one seen: another process may have just taken it over.
      if ((await io.stat(path).catch(() => null))?.mtimeMs === held.mtimeMs) await io.run(removeLockArgv(path, options.isWindows), { timeoutMs: 10_000 })
      continue
    }
    if (attempt + 1 < options.tries) await io.sleep(retryDelay(attempt))
  }

  throw new LockBusyError(`the lock ${path} is held by another process`)
}

/** Runs `work` holding the lock at `path`, and gives the lock up after, whatever `work` did. */
export async function withLock<T>(io: Io, path: string, options: LockOptions, work: (lock: Lock) => Promise<T>): Promise<T> {
  const lock = await acquire(io, path, options)
  try {
    return await work(lock)
  } finally {
    await lock.release().catch((error: unknown) => io.log(`cannot release ${path}: ${error instanceof Error ? error.message : String(error)}`))
  }
}

files.hooks/orca.ts:
/**
 * Orca keeps Claude logins of its own. While one of them is selected there,
 * Orca writes it into Claude Code's login (the keychain items, the credentials
 * file and `oauthAccount` in `~/.claude.json`) each time it launches Claude,
 * fetches the rate limits or starts, so a login changed anywhere else is put
 * back at Orca's next write. A switch therefore selects the account in Orca
 * too, and a login Orca keeps a copy of is never refreshed here: refreshing it
 * would spend the refresh token Orca's copy holds.
 *
 * These helpers read what Orca says and build what is sent to it; the hooks
 * module talks to Orca's runtime through them where its `orca-runtime.json`
 * says, as Orca's own CLI does: its Unix socket through `perl` on macOS and
 * Linux, its named pipe through PowerShell on Windows.
 */

/** A Claude account Orca keeps. */
export type OrcaAccount = { id: string; email: string; organizationUuid: string | null }

/** Orca's Claude logins: the accounts it keeps, and the one it writes into Claude Code (null when it leaves the login alone). */
export type OrcaClaude = { accounts: OrcaAccount[]; activeId: string | null }

/** Where Orca's running app answers, from the `orca-runtime.json` it writes: a Unix socket, or a named pipe on Windows. */
export type OrcaRuntime = { endpoint: string; authToken: string }

/** How Orca's runtime is reached on a platform: its Unix socket, or on Windows its named pipe. */
export type OrcaTransport = 'unix' | 'named-pipe'

/** What came of asking Orca: not installed, installed but not running, running but not answering, or its answer. */
export type OrcaReach = { kind: 'absent' } | { kind: 'down' } | { kind: 'unreachable'; reason: string } | { kind: 'ok'; claude: OrcaClaude }

/** The file in Orca's data folder that names its runtime's endpoint (a socket, or a named pipe on Windows) and token. */
export const ORCA_RUNTIME_FILE = 'orca-runtime.json'

/** How long a selection asked while Orca was closed waits for Orca to run again. */
export const ORCA_PENDING_KEPT_MS = 7 * 24 * 60 * 60 * 1000

/**
 * Orca's data folder, found as Orca's CLI finds it: `ORCA_USER_DATA_PATH`
 * (set in Orca's own terminals), else the platform's application data folder;
 * null on Windows without `APPDATA`.
 */
export function orcaDataDirectory(place: { userDataVariable?: string; home: string; isMac: boolean; isWindows: boolean; xdgConfigHome?: string; appData?: string }): string | null {
  if (place.userDataVariable) return place.userDataVariable
  if (place.isWindows) return place.appData ? `${place.appData.replaceAll('\\', '/')}/orca` : null
  if (place.isMac) return `${place.home}/Library/Application Support/orca`

  return `${place.xdgConfigHome || `${place.home}/.config`}/orca`
}

/** The runtime's endpoint for the transport this platform uses, and its token, from `orca-runtime.json`; null when it names neither. */
export function parseOrcaRuntime(text: string, transport: OrcaTransport): OrcaRuntime | null {
  let metadata: { transports?: unknown; authToken?: unknown }
  try {
    metadata = JSON.parse(text) as { transports?: unknown; authToken?: unknown }
  } catch (error) {
    if (error instanceof SyntaxError) return null
    throw error
  }
  if (typeof metadata.authToken !== 'string' || metadata.authToken === '' || !Array.isArray(metadata.transports)) return null
  const found = (metadata.transports as { kind?: unknown; endpoint?: unknown }[]).find(one => one.kind === transport && typeof one.endpoint === 'string' && one.endpoint !== '')

  return found ? { endpoint: found.endpoint as string, authToken: metadata.authToken } : null
}

/** One request to Orca's runtime as a line of JSON; it carries the token, so it goes on stdin, never in argv. */
export function orcaRequestLine(id: string, authToken: string, method: string, params?: unknown): string {
  return `${JSON.stringify(params === undefined ? { id, authToken, method } : { id, authToken, method, params })}\n`
}

/** Orca's answer to one request: its result, or the reason it gave. */
export type OrcaFrame = { ok: true; result: unknown } | { ok: false; reason: string }

/** The answer in what the runtime sent, keepalive lines skipped; null when no answer to `id` is there. */
export function parseOrcaFrame(text: string, id: string): OrcaFrame | null {
  for (const line of text.split('\n')) {
    if (line.trim() === '') continue
    let frame: { id?: unknown; ok?: unknown; result?: unknown; error?: { message?: unknown } | null; _keepalive?: unknown }
    try {
      frame = JSON.parse(line) as typeof frame
    } catch (error) {
      if (error instanceof SyntaxError) continue
      throw error
    }
    if (frame._keepalive === true || frame.id !== id) continue
    if (frame.ok === true) return { ok: true, result: frame.result }

    return { ok: false, reason: typeof frame.error?.message === 'string' ? frame.error.message : 'Orca refused the request' }
  }

  return null
}

/** The Claude part of what `accounts.list` answers, or null when it holds none. */
export function parseOrcaClaude(result: unknown): OrcaClaude | null {
  const claude = (result as { claude?: { accounts?: unknown; activeAccountId?: unknown; activeAccountIdsByRuntime?: { host?: unknown } } } | null)?.claude
  if (!claude || !Array.isArray(claude.accounts)) return null
  const accounts = (claude.accounts as { id?: unknown; email?: unknown; organizationUuid?: unknown; managedAuthRuntime?: unknown }[])
    // A login Orca keeps in a WSL distribution is written there, not into this machine's Claude Code.
    .filter(account => typeof account.id === 'string' && typeof account.email === 'string' && (account.managedAuthRuntime ?? 'host') === 'host')
    .map(account => ({
      id: account.id as string,
      email: account.email as string,
      organizationUuid: typeof account.organizationUuid === 'string' && account.organizationUuid !== '' ? account.organizationUuid : null,
    }))
  const host = claude.activeAccountIdsByRuntime?.host
  const active = host === undefined ? claude.activeAccountId : host
  const activeId = typeof active === 'string' && accounts.some(account => account.id === active) ? active : null

  return { accounts, activeId }
}

/**
 * The account Orca keeps for a login, matched as Orca matches its own: the
 * same email, ignoring case, and the same organization. Without the
 * organization the email decides, when only one account holds it.
 */
export function orcaAccountFor(claude: OrcaClaude, email: string, organizationUuid?: string | null): OrcaAccount | undefined {
  const sameEmail = claude.accounts.filter(account => account.email.trim().toLowerCase() === email.trim().toLowerCase())
  if (organizationUuid) return sameEmail.find(account => account.organizationUuid === organizationUuid)

  return sameEmail.length === 1 ? sameEmail[0] : undefined
}

/** The email of the account Orca writes into Claude Code, or null when it leaves the login alone. */
export function orcaActiveEmail(claude: OrcaClaude | null): string | null {
  return claude?.accounts.find(account => account.id === claude.activeId)?.email ?? null
}

/**
 * How a switch to an account goes with Orca as it stands:
 * - `direct`: Orca is not installed, or leaves Claude Code's login alone;
 * - `select`: Orca runs and keeps the account, so it is selected there too;
 * - `refuse`: Orca runs, writes another login and keeps none for this account, so it would put its own back;
 * - `pending`: Orca keeps the account but does not run now; it is selected once Orca answers again;
 * - `warn`: Orca does not run now and keeps no login for the account; it puts its own back when it starts.
 *
 * `remembered` is what Orca said last, for when it does not answer now.
 */
export type OrcaPlan =
  | { kind: 'direct' }
  | { kind: 'select'; account: OrcaAccount; activeId: string | null }
  | { kind: 'refuse'; activeEmail: string | null }
  | { kind: 'pending'; account: OrcaAccount; activeId: string | null }
  | { kind: 'warn'; activeEmail: string | null }

export function planSwitch(reach: OrcaReach, remembered: OrcaClaude | null, email: string, organizationUuid?: string | null): OrcaPlan {
  if (reach.kind === 'absent') return { kind: 'direct' }
  if (reach.kind === 'ok') {
    if (reach.claude.activeId === null) return { kind: 'direct' }
    const account = orcaAccountFor(reach.claude, email, organizationUuid)

    return account ? { kind: 'select', account, activeId: reach.claude.activeId } : { kind: 'refuse', activeEmail: orcaActiveEmail(reach.claude) }
  }
  if (!remembered || remembered.activeId === null) return { kind: 'direct' }
  const account = orcaAccountFor(remembered, email, organizationUuid)

  return account ? { kind: 'pending', account, activeId: remembered.activeId } : { kind: 'warn', activeEmail: orcaActiveEmail(remembered) }
}

/**
 * What a change of the login, made by no switch of this mod, means with Orca:
 * - `none`: Orca is not there, or leaves Claude Code's login alone;
 * - `orca`: the login is now the account Orca writes, so Orca made the change;
 * - `follow`: the login is an account Orca keeps but does not write, so Orca is told to write it, or it would put its own back;
 * - `revert`: the login is an account Orca keeps no copy of; Orca puts its own back at its next write.
 */
export type OrcaFollow = { kind: 'none' } | { kind: 'orca' } | { kind: 'follow'; account: OrcaAccount } | { kind: 'revert'; activeEmail: string | null }

export function planFollow(claude: OrcaClaude | null, email: string, organizationUuid?: string | null): OrcaFollow {
  if (!claude || claude.activeId === null) return { kind: 'none' }
  const account = orcaAccountFor(claude, email, organizationUuid)
  if (account?.id === claude.activeId) return { kind: 'orca' }

  return account ? { kind: 'follow', account } : { kind: 'revert', activeEmail: orcaActiveEmail(claude) }
}

/**
 * Whether Orca keeps a copy of this login, selected or not: refreshing the
 * token here would spend the refresh token that copy holds, and Orca would
 * later write a spent login into Claude Code.
 */
export function isKeptByOrca(claude: OrcaClaude | null, email: string, organizationUuid?: string | null): boolean {
  return claude !== null && orcaAccountFor(claude, email, organizationUuid) !== undefined
}

/** A selection asked while Orca was not running: the account, and the one Orca wrote then. */
export type OrcaPending = { accountId: string; email: string; activeBefore: string | null; at: number }

/**
 * What to do with a pending selection now that Orca answers: `apply` it;
 * `done` when Orca already writes that account; `drop` it when it is a week
 * old, Orca no longer keeps the account, or someone picked another account in
 * Orca since (Orca writes neither the account then nor the one asked).
 */
export function pendingStep(pending: OrcaPending, claude: OrcaClaude, now: number): 'apply' | 'done' | 'drop' {
  if (claude.activeId === pending.accountId) return 'done'
  if (now - pending.at > ORCA_PENDING_KEPT_MS) return 'drop'
  if (!claude.accounts.some(account => account.id === pending.accountId)) return 'drop'

  return claude.activeId === pending.activeBefore ? 'apply' : 'drop'
}

/** Reads a pending selection kept in the store, or null. */
export function asPending(value: unknown): OrcaPending | null {
  const pending = value as Partial<OrcaPending> | null | undefined
  if (!pending || typeof pending.accountId !== 'string' || typeof pending.email !== 'string' || typeof pending.at !== 'number') return null

  return { accountId: pending.accountId, email: pending.email, activeBefore: typeof pending.activeBefore === 'string' ? pending.activeBefore : null, at: pending.at }
}

/** Reads what Orca said last, kept in the store as `{ claude: OrcaClaude }`, or null. */
export function asRemembered(value: unknown): OrcaClaude | null {
  const claude = (value as { claude?: { accounts?: unknown; activeId?: unknown } } | null | undefined)?.claude
  if (!claude || !Array.isArray(claude.accounts)) return null
  const accounts = (claude.accounts as Partial<OrcaAccount>[])
    .filter(account => typeof account.id === 'string' && typeof account.email === 'string')
    .map(account => ({ id: account.id as string, email: account.email as string, organizationUuid: typeof account.organizationUuid === 'string' ? account.organizationUuid : null }))
  const activeId = typeof claude.activeId === 'string' && accounts.some(account => account.id === claude.activeId) ? claude.activeId : null

  return { accounts, activeId }
}

/** How the clients below end: 0 printed an answer; the rest say why there is none. */
export const ORCA_EXIT = { answered: 0, cannotConnect: 2, timedOut: 3, closed: 4, cannotSend: 5 } as const

/** The pipe's name as .NET takes it: the endpoint without its `\\.\pipe\` prefix. */
export function pipeName(endpoint: string): string {
  return endpoint.replace(/^\\\\\.\\pipe\\/i, '').replace(/^\/\/\.\/pipe\//i, '')
}

/**
 * A client for Orca's runtime on Windows, as a PowerShell script: it connects
 * to the named pipe, sends the request line it reads from stdin, and prints the
 * first line back that is not a keepalive, within `seconds`. Its exit codes
 * are those of the Perl client.
 */
export function orcaPipeScript(endpoint: string, seconds: number): string {
  const name = pipeName(endpoint).replace(/'/g, "''")

  return [
    "$ErrorActionPreference = 'Stop'",
    '$utf8 = New-Object System.Text.UTF8Encoding($false)',
    `$pipe = New-Object System.IO.Pipes.NamedPipeClientStream('.', '${name}', [System.IO.Pipes.PipeDirection]::InOut)`,
    `try { $pipe.Connect(${Math.min(seconds, 5) * 1000}) } catch { [Console]::Error.WriteLine($_.Exception.Message); exit ${ORCA_EXIT.cannotConnect} }`,
    '$reader = New-Object System.IO.StreamReader($pipe, $utf8)',
    '$writer = New-Object System.IO.StreamWriter($pipe, $utf8)',
    '$writer.AutoFlush = $true',
    '$request = [Console]::In.ReadToEnd()',
    'if (-not $request.EndsWith("`n")) { $request += "`n" }',
    `try { $writer.Write($request) } catch { [Console]::Error.WriteLine($_.Exception.Message); exit ${ORCA_EXIT.cannotSend} }`,
    `$deadline = [DateTime]::UtcNow.AddSeconds(${seconds})`,
    'while ($true) {',
    '  $task = $reader.ReadLineAsync()',
    '  $left = ($deadline - [DateTime]::UtcNow).TotalMilliseconds',
    `  if ($left -le 0 -or -not $task.Wait([int]$left)) { [Console]::Error.WriteLine('timed out'); exit ${ORCA_EXIT.timedOut} }`,
    '  $line = $task.Result',
    `  if ($null -eq $line) { [Console]::Error.WriteLine('closed'); exit ${ORCA_EXIT.closed} }`,
    '  if ($line.Trim() -eq \'\' -or $line -match \'^\\s*\\{\\s*"_keepalive"\\s*:\\s*true\\s*\\}\\s*$\') { continue }',
    '  [Console]::Out.WriteLine($line)',
    `  exit ${ORCA_EXIT.answered}`,
    '}',
  ].join('\n')
}

/**
 * A client for Orca's runtime in Perl, which macOS and Linux both carry: it
 * connects to the socket in its first argument, sends the request line it
 * reads from stdin, and prints the first line back that is not a keepalive,
 * within the seconds in its second argument.
 */
export const ORCA_CLIENT_SCRIPT = [
  'use strict; use warnings; use IO::Socket::UNIX; use Socket qw(SOCK_STREAM);',
  `$SIG{ALRM} = sub { print STDERR "timed out\\n"; exit ${ORCA_EXIT.timedOut} };`,
  'alarm($ARGV[1]);',
  `my $socket = IO::Socket::UNIX->new(Type => SOCK_STREAM, Peer => $ARGV[0]) or do { print STDERR "$!\\n"; exit ${ORCA_EXIT.cannotConnect} };`,
  'my $request = do { local $/; <STDIN> };',
  `print {$socket} $request or do { print STDERR "$!\\n"; exit ${ORCA_EXIT.cannotSend} };`,
  '$socket->flush;',
  'while (defined(my $line = <$socket>)) {',
  '  next if $line =~ /^\\s*$/ || $line =~ /^\\s*\\{\\s*"_keepalive"\\s*:\\s*true\\s*\\}\\s*$/;',
  '  print $line;',
  `  exit ${ORCA_EXIT.answered};`,
  '}',
  `print STDERR "closed\\n"; exit ${ORCA_EXIT.closed};`,
].join('\n')

files.hooks/orcaClient.ts:
import { homeDirectory, platformOf } from './credentials'
import type { Messages } from './i18n'
import type { Io } from './io'
import { message } from './io'
import {
  ORCA_CLIENT_SCRIPT,
  ORCA_EXIT,
  ORCA_RUNTIME_FILE,
  asPending,
  asRemembered,
  orcaDataDirectory,
  orcaPipeScript,
  orcaRequestLine,
  parseOrcaClaude,
  parseOrcaFrame,
  parseOrcaRuntime,
} from './orca'
import type { OrcaAccount, OrcaClaude, OrcaPending, OrcaReach } from './orca'
import { encodePowerShell } from './shared/files'

/**
 * Asking Orca's running app: its Claude accounts (`accounts.list`) and
 * selecting one (`accounts.selectClaude`), through the socket or named pipe
 * its `orca-runtime.json` names, as Orca's own CLI does. What it said last is
 * kept in the store for every session, Orca closed included.
 */

/** The `$.store` key of what Orca said last. */
const ORCA_KEY = 'orca'
/** The `$.store` key of a selection a switch asked while Orca was not answering, made once it answers. */
const ORCA_PENDING_KEY = 'orcaPending'
/** How often, machine-wide, the tick asks Orca for its accounts again. */
const ORCA_RECHECK_MS = 5 * 60 * 1000
/** How long what Orca said last is trusted while it does not run: after two weeks it is taken as no longer used. */
const ORCA_FORGET_MS = 14 * 24 * 60 * 60 * 1000
/** How long Orca has to answer, in seconds: selecting an account may refresh its token first. */
const ORCA_LIST_SECONDS = 10
const ORCA_SELECT_SECONDS = 30

type OrcaAnswer = { kind: 'absent' } | { kind: 'down' } | { kind: 'unreachable'; reason: string } | { kind: 'ok'; result: unknown }

/** Orca's data folder on this machine, or null where none can be named. */
async function orcaDirectory(io: Io): Promise<string | null> {
  const platform = await platformOf(io)

  return orcaDataDirectory({
    userDataVariable: await io.env('ORCA_USER_DATA_PATH'),
    home: await homeDirectory(io),
    isMac: platform.backend === 'keychain',
    isWindows: platform.isWindows,
    xdgConfigHome: await io.env('XDG_CONFIG_HOME'),
    appData: await io.env('APPDATA'),
  })
}

/**
 * Sends one request to Orca's runtime and reads the answer. Orca is `absent`
 * when its data folder is not there, `down` when nothing answers, and
 * `unreachable` when the client cannot run, times out or Orca refuses.
 */
async function orcaRequest(io: Io, m: Messages, method: string, params: unknown, seconds: number): Promise<OrcaAnswer> {
  const directory = await orcaDirectory(io)
  if (directory === null || !(await io.exists(directory))) return { kind: 'absent' }
  const { isWindows } = await platformOf(io)
  const metadataPath = `${directory}/${ORCA_RUNTIME_FILE}`
  // Installed, but no runtime says where it answers: Orca is not running.
  const runtime = (await io.exists(metadataPath)) ? parseOrcaRuntime(await io.read(metadataPath), isWindows ? 'named-pipe' : 'unix') : null
  if (!runtime) return { kind: 'down' }
  const id = crypto.randomUUID()
  const argv = isWindows
    ? ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(orcaPipeScript(runtime.endpoint, seconds))]
    : ['perl', '-e', ORCA_CLIENT_SCRIPT, runtime.endpoint, String(seconds)]
  let run: { exitCode: number; stdout: string; stderr: string }
  try {
    run = await io.run(argv, { stdin: orcaRequestLine(id, runtime.authToken, method, params), timeoutMs: (seconds + 5) * 1000 })
  } catch (error) {
    return { kind: 'unreachable', reason: message(error) }
  }
  if (run.exitCode === ORCA_EXIT.cannotConnect) return { kind: 'down' }
  if (run.exitCode === -1 && /failed to start|ENOENT/.test(run.stderr)) return { kind: 'unreachable', reason: isWindows ? m.orcaNeedsPowerShell : m.orcaNeedsPerl }
  if (run.exitCode !== ORCA_EXIT.answered) return { kind: 'unreachable', reason: run.stderr.trim() || `exit ${run.exitCode}` }
  const frame = parseOrcaFrame(run.stdout, id)
  if (!frame) return { kind: 'unreachable', reason: m.orcaNoAnswer }

  return frame.ok ? { kind: 'ok', result: frame.result } : { kind: 'unreachable', reason: frame.reason }
}

/** Asks Orca for its Claude logins, and keeps what it says for every session. */
export async function orcaClaude(io: Io, m: Messages): Promise<OrcaReach> {
  const answer = await orcaRequest(io, m, 'accounts.list', undefined, ORCA_LIST_SECONDS)
  const now = await io.now()
  if (answer.kind === 'absent') {
    await io.store.delete(ORCA_KEY)
    await io.store.delete(ORCA_PENDING_KEY)

    return answer
  }
  const kept = ((await io.store.get(ORCA_KEY)) ?? {}) as Record<string, unknown>
  if (answer.kind !== 'ok') {
    await io.store.set(ORCA_KEY, { ...kept, checkedAt: now })

    return answer
  }
  const claude = parseOrcaClaude(answer.result)
  if (!claude) {
    await io.store.set(ORCA_KEY, { ...kept, checkedAt: now })

    return { kind: 'unreachable', reason: m.orcaNoAnswer }
  }
  await io.store.set(ORCA_KEY, { claude, seenAt: now, checkedAt: now })

  return { kind: 'ok', claude }
}

/** What Orca said last, while it is recent enough to trust; null with nothing said. */
export async function rememberedOrca(io: Io): Promise<OrcaClaude | null> {
  const kept = (await io.store.get(ORCA_KEY)) as { seenAt?: unknown } | undefined
  if (typeof kept?.seenAt !== 'number' || (await io.now()) - kept.seenAt > ORCA_FORGET_MS) return null

  return asRemembered(kept)
}

/** Whether the tick asks Orca again now: every few minutes machine-wide, and every tick while a selection waits for it. */
export async function isOrcaCheckDue(io: Io): Promise<boolean> {
  if (asPending(await io.store.get(ORCA_PENDING_KEY))) return true
  const kept = (await io.store.get(ORCA_KEY)) as { checkedAt?: unknown } | undefined

  return typeof kept?.checkedAt !== 'number' || (await io.now()) - kept.checkedAt >= ORCA_RECHECK_MS
}

/** Selects a Claude account in Orca, which then writes it into Claude Code's login itself. */
export async function orcaSelect(io: Io, m: Messages, accountId: string): Promise<void> {
  const answer = await orcaRequest(io, m, 'accounts.selectClaude', { accountId }, ORCA_SELECT_SECONDS)
  if (answer.kind === 'ok') return
  throw new Error(answer.kind === 'unreachable' ? answer.reason : m.orcaNotRunning)
}

/** Keeps a selection for Orca to make once it answers, and the account Orca wrote when it was asked. */
export async function keepPending(io: Io, account: OrcaAccount, activeBefore: string | null): Promise<void> {
  const pending: OrcaPending = { accountId: account.id, email: account.email, activeBefore, at: await io.now() }
  await io.store.set(ORCA_PENDING_KEY, pending)
}

/** Takes the waiting selection off the store, so no other session makes it too; null when none waits. */
export async function takePending(io: Io): Promise<OrcaPending | null> {
  const pending = asPending(await io.store.get(ORCA_PENDING_KEY))
  if (pending) await io.store.delete(ORCA_PENDING_KEY)

  return pending
}

/** Puts a selection back to wait, when making it failed. */
export async function returnPending(io: Io, pending: OrcaPending): Promise<void> {
  await io.store.set(ORCA_PENDING_KEY, pending)
}

/** Drops any waiting selection: a switch with nothing to bring Orca to. */
export async function dropPending(io: Io): Promise<void> {
  await io.store.delete(ORCA_PENDING_KEY)
}

files.hooks/queue.ts:
/**
 * Work run one piece at a time, in the order asked: each piece starts once
 * the one before has settled, whether it resolved or threw, and its own
 * result or error goes to its caller alone.
 *
 * A piece must not wait on another piece of the same queue: it would wait
 * for itself.
 */
export function serialQueue(): <T>(work: () => Promise<T>) => Promise<T> {
  let tail: Promise<unknown> = Promise.resolve()

  return <T>(work: () => Promise<T>): Promise<T> => {
    const run = tail.then(work, work)
    tail = run.catch(() => undefined)

    return run
  }
}

files.hooks/switchlog.ts:
/**
 * The record of every change of the login Claude Code uses: each switch this
 * mod makes, and each change it finds that no switch of its made. Kept as one
 * JSON line per change, so a change nobody asked for can be traced to the
 * session that made it, or shown to have come from outside the mod.
 */

/** One change of the live login. */
export type LoginChange = {
  /** Milliseconds since the epoch. */
  at: number
  /**
   * `switch`: this mod switched; `heal`: this mod put the configured account's saved login back after
   * Claude Code's was rejected; `orca`: Orca wrote the account selected in it; `follow`: this mod selected
   * in Orca the login that changed outside it, or the account a switch chose while Orca was not running;
   * `outside`: the login changed with no switch or heal of this mod's just before, and not to Orca's.
   */
  kind: 'switch' | 'heal' | 'orca' | 'follow' | 'outside'
  /** The session that made or noticed the change, its folder and the mod's version there. */
  session: string
  cwd: string
  version: string
  /** How a switch was asked for: the Switch dialog or the `use` command. */
  via?: 'dialog' | 'command'
  /** What a switch did about Orca: nothing (`direct`), selected the account there (`select`), left it to be selected once Orca runs (`pending`), or could not (`warn`). */
  orca?: 'direct' | 'select' | 'pending' | 'warn'
  /** A switch that could not write the login, recorded after the line that announced it; the login was put back. */
  failed?: true
  /** The emails before and after; null when unknown. */
  from: string | null
  to: string
}

/** How long after a switch of this mod's a change to the same account is that switch's, in any session. */
export const OWN_SWITCH_MS = 2 * 60 * 1000
/** The most lines the record keeps: the oldest go first. */
export const CHANGES_KEPT = 200

/** The record's lines as changes, a line that does not parse left out. */
export function parseChanges(text: string): LoginChange[] {
  return text
    .split('\n')
    .filter(line => line.trim() !== '')
    .flatMap(line => {
      try {
        return [JSON.parse(line) as LoginChange]
      } catch {
        return []
      }
    })
}

/** The record with one more change, cut to the newest `CHANGES_KEPT`. */
export function withChange(text: string, change: LoginChange): string {
  const lines = [...text.split('\n').filter(line => line.trim() !== ''), JSON.stringify(change)]

  return `${lines.slice(-CHANGES_KEPT).join('\n')}\n`
}

/**
 * Whether a switch, a heal or an Orca selection of this mod's, in any session,
 * made the login `to` shortly before `at`. A switch the same session then
 * recorded as failed made nothing.
 */
export function isOwnSwitch(changes: readonly LoginChange[], to: string, at: number): boolean {
  const isFailed = (change: LoginChange) =>
    changes.some(later => later.failed === true && later.kind === 'switch' && later.session === change.session && later.to === change.to && later.at >= change.at && later.at - change.at <= OWN_SWITCH_MS)

  return changes.some(
    change =>
      (change.kind === 'switch' || change.kind === 'heal' || change.kind === 'follow') &&
      change.failed !== true &&
      change.to === to &&
      at - change.at >= -5_000 &&
      at - change.at <= OWN_SWITCH_MS &&
      !(change.kind === 'switch' && isFailed(change)),
  )
}

files.hooks/writes.ts:
import type { Io } from './io'
import { encodePowerShell, powerShellLiteral } from './shared/files'

/**
 * Replacing a file whole, so a reader never meets it half written: the text
 * goes to a new file beside it, which is then renamed over it. A file another
 * program reads while this one writes (Claude Code's `.credentials.json` and
 * `~/.claude.json`) is never truncated in place.
 */

/**
 * argv writing stdin over the file `$0` on a POSIX shell. A link is followed
 * to the file it names, so the link stays. A private file is owner-only
 * (mode 600, the temporary file `mktemp` makes), and so is a folder made for
 * it; another gets mode 644.
 */
export function atomicWriteArgv(path: string, isPrivate: boolean): string[] {
  const script = [
    'set -e',
    '[ "$1" = private ] && umask 077',
    'target=$0',
    'while [ -L "$target" ]; do link=$(readlink "$target"); case $link in /*) target=$link ;; *) target=$(dirname "$target")/$link ;; esac; done',
    'dir=$(dirname "$target")',
    'mkdir -p "$dir"',
    'tmp=$(mktemp "$dir/.sc-accounts.XXXXXX")',
    'trap \'rm -f "$tmp"\' EXIT',
    'cat > "$tmp"',
    '[ "$1" = private ] || chmod 644 "$tmp"',
    'mv -f "$tmp" "$target"',
  ].join('\n')

  return ['/bin/sh', '-c', script, path, isPrivate ? 'private' : 'shared']
}

/** argv putting `temporary` in place of `path` on Windows: `File.Replace` over a file there, a move otherwise. */
export function windowsReplaceArgv(temporary: string, path: string): string[] {
  const script = `$t = ${powerShellLiteral(temporary)}; $d = ${powerShellLiteral(path)}; if (Test-Path -LiteralPath $d -PathType Leaf) { [System.IO.File]::Replace($t, $d, $null) } else { [System.IO.File]::Move($t, $d) }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/** Replaces `path` with `text` atomically; on Windows the profile folder's access list keeps a private file private. */
export async function writeAtomic(io: Io, path: string, text: string, options: { isPrivate: boolean; isWindows: boolean }): Promise<void> {
  if (options.isWindows) {
    const temporary = `${path}.sc-accounts-${crypto.randomUUID()}.tmp`
    await io.write(temporary, text)
    const moved = await io.run(windowsReplaceArgv(temporary, path), { timeoutMs: 10_000 })
    if (moved.exitCode !== 0) throw new Error(`cannot write ${path}: ${moved.stderr.trim()}`)

    return
  }
  const written = await io.run(atomicWriteArgv(path, options.isPrivate), { stdin: text, timeoutMs: 10_000 })
  if (written.exitCode !== 0) throw new Error(`cannot write ${path}: ${written.stderr.trim()}`)
}

files.hooks/shared/files.ts:
// Copied from shared/ by scripts/sync.mjs; edit shared/ and run the script.
/**
 * Deleting files by argv on every platform, with no shell to read the paths.
 *
 * Claude Code starts a plugin's command without a shell. On a POSIX system
 * `rm -f -- <paths>` takes each path as one argument. Windows has no `rm`,
 * and `cmd.exe /c del` would read the paths again by cmd's own rules (`%VAR%`
 * expanded, quotes stripped), so there PowerShell runs `Remove-Item
 * -LiteralPath` from an encoded script: the paths travel inside the script as
 * single-quoted literals and are never parsed as a command line.
 */

/** The script as PowerShell's `-EncodedCommand` takes it: UTF-16LE, then base64. */
export function encodePowerShell(script: string): string {
  let bytes = ''
  for (let index = 0; index < script.length; index += 1) {
    const unit = script.charCodeAt(index)
    bytes += String.fromCharCode(unit & 0xff, unit >> 8)
  }

  return btoa(bytes)
}

/**
 * A path as a PowerShell single-quoted literal: nothing in it is special but
 * a single quote, which PowerShell also reads in its curly forms (‘ ’ ‚ ‛);
 * each is doubled.
 */
export function powerShellLiteral(path: string): string {
  return `'${path.replace(/['\u2018\u2019\u201a\u201b]/g, quote => quote + quote)}'`
}

/** argv deleting `paths`, absent or not; relative paths resolve against the command's working directory. */
export function removeArgv(paths: readonly string[], isWindows: boolean): string[] {
  if (!isWindows) return ['rm', '-f', '--', ...paths]
  // Only files are deleted, and an absent path is passed over: Remove-Item on a directory with
  // children asks whether to go on, a question no plugin answers. A file that cannot be deleted
  // stops the script, which exits 1.
  const script = `foreach ($p in @(${paths.map(powerShellLiteral).join(',')})) { if (Test-Path -LiteralPath $p -PathType Leaf) { Remove-Item -LiteralPath $p -Force -ErrorAction Stop } }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

/**
 * argv deleting `paths` with everything under them, absent or not: a session's
 * transcript and its folder of subagent transcripts and tool output. The
 * caller checks every path lies where it means to delete; nothing here does.
 */
export function removeTreeArgv(paths: readonly string[], isWindows: boolean): string[] {
  if (!isWindows) return ['rm', '-rf', '--', ...paths]
  // -Recurse with -Force asks nothing: a folder with children is deleted whole.
  const script = `foreach ($p in @(${paths.map(powerShellLiteral).join(',')})) { if (Test-Path -LiteralPath $p) { Remove-Item -LiteralPath $p -Recurse -Force -ErrorAction Stop } }`

  return ['powershell.exe', '-NoProfile', '-NonInteractive', '-EncodedCommand', encodePowerShell(script)]
}

files.hooks/storage.ts:
import type { StorageProject, StorageView } from '../types'

/**
 * What Claude Code keeps on this machine under its config directory, and
 * which sessions a cleanup would delete. Pure: the hooks module walks the
 * folders and deletes; this file only adds up and chooses.
 */

/** A file under the projects folder: its path from there, its size and when it last changed. */
export type StorageFile = { relative: string; size: number; mtimeMs: number }

/** One session's files: its transcript, and its folder of subagent transcripts and tool output. */
export type StorageSession = {
  /** The project folder it is kept in. */
  folder: string
  session: string
  bytes: number
  /** `mtimeMs` of its newest file. */
  lastActive: number
  /** Paths from the projects folder to delete it: the transcript and the session's folder, those that exist. */
  paths: string[]
}

/** What the projects folder holds, by kind and by project; the folders and settings beside it are added by the caller. */
export type StorageSummary = Pick<StorageView, 'bytes' | 'transcripts' | 'subagents' | 'other' | 'sessions'> & { projects: Omit<StorageProject, 'name'>[] }

/** The project folder, the session and whether the path is the session's transcript, from a path under the projects folder. */
function placeOf(relative: string): { folder: string; session: string; isTranscript: boolean } | null {
  const parts = relative.split('/').filter(Boolean)
  if (parts.length < 2) return null
  const [folder = '', second = ''] = parts
  if (parts.length === 2) return second.endsWith('.jsonl') ? { folder, session: second.slice(0, -'.jsonl'.length), isTranscript: true } : null

  return { folder, session: second, isTranscript: false }
}

/** The files grouped by session, each with what deleting it removes. */
export function sessionsOf(files: StorageFile[]): StorageSession[] {
  const byKey = new Map<string, StorageSession & { hasTranscript: boolean; hasFolder: boolean }>()
  for (const file of files) {
    const place = placeOf(file.relative)
    if (!place) continue
    const key = `${place.folder}/${place.session}`
    const known = byKey.get(key) ?? { folder: place.folder, session: place.session, bytes: 0, lastActive: 0, paths: [], hasTranscript: false, hasFolder: false }
    known.bytes += file.size
    known.lastActive = Math.max(known.lastActive, file.mtimeMs)
    if (place.isTranscript) known.hasTranscript = true
    else known.hasFolder = true
    byKey.set(key, known)
  }

  return [...byKey.values()].map(({ hasTranscript, hasFolder, ...session }) => ({
    ...session,
    paths: [...(hasTranscript ? [`${session.folder}/${session.session}.jsonl`] : []), ...(hasFolder ? [`${session.folder}/${session.session}`] : [])],
  }))
}

/** What the projects folder holds, by kind and by project. */
export function summarizeStorage(files: StorageFile[]): StorageSummary {
  const add = (into: { count: number; bytes: number }, size: number) => ({ count: into.count + 1, bytes: into.bytes + size })
  let transcripts = { count: 0, bytes: 0 }
  let subagents = { count: 0, bytes: 0 }
  let other = { count: 0, bytes: 0 }
  for (const file of files) {
    const place = placeOf(file.relative)
    if (place?.isTranscript) transcripts = add(transcripts, file.size)
    else if (file.relative.endsWith('.jsonl') && file.relative.includes('/subagents/')) subagents = add(subagents, file.size)
    else other = add(other, file.size)
  }
  const sessions = sessionsOf(files)
  const byFolder = new Map<string, Omit<StorageProject, 'name'>>()
  for (const session of sessions) {
    const known = byFolder.get(session.folder) ?? { folder: session.folder, bytes: 0, sessions: 0, lastActive: 0 }
    byFolder.set(session.folder, {
      folder: session.folder,
      bytes: known.bytes + session.bytes,
      sessions: known.sessions + 1,
      lastActive: Math.max(known.lastActive, session.lastActive),
    })
  }

  return {
    bytes: transcripts.bytes + subagents.bytes + other.bytes,
    transcripts,
    subagents,
    other,
    sessions: sessions.length,
    projects: [...byFolder.values()].sort((a, b) => b.bytes - a.bytes),
  }
}

/**
 * The sessions a cleanup deletes: every one whose newest file is older than
 * `days` days, but never one of `keep` (the sessions running now).
 */
export function cleanupPlan(sessions: StorageSession[], days: number, now: number, keep: readonly string[]): { sessions: StorageSession[]; bytes: number } {
  const before = now - days * 86_400_000
  const chosen = sessions.filter(session => session.lastActive < before && !keep.includes(session.session))

  return { sessions: chosen, bytes: chosen.reduce((sum, session) => sum + session.bytes, 0) }
}

/**
 * The sessions running Claude Code processes name in their command lines, one
 * process a line: the id after `--resume`, `-r` or `--session-id`. A session
 * resumed in another window but idle past a cleanup's age is still in use.
 */
export function sessionIdsInCommands(commandLines: string): string[] {
  const ids = new Set<string>()
  const id = '([0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12})'
  for (const line of commandLines.split('\n')) {
    if (!/claude/i.test(line)) continue
    for (const match of line.matchAll(new RegExp(`(?:--resume|--session-id|-r)(?:=|\\s+)${id}`, 'g'))) if (match[1]) ids.add(match[1].toLowerCase())
  }

  return [...ids]
}

/**
 * The sessions a cleanup deletes now: those planned now that the dialog also
 * showed when the person confirmed it. A session that went idle past the age
 * between the two was never asked about, and stays.
 */
export function confirmedSessions(planned: StorageSession[], confirmed: ReadonlySet<string>): StorageSession[] {
  return planned.filter(session => confirmed.has(`${session.folder}/${session.session}`))
}

/** A size in a few characters: `512 B`, `12.4 KB`, `221.6 MB`, `17.0 GB`. */
export function byteSize(bytes: number): string {
  const units: [number, string][] = [
    [1024 ** 3, 'GB'],
    [1024 ** 2, 'MB'],
    [1024, 'KB'],
  ]
  for (const [size, unit] of units) if (bytes >= size) return `${(bytes / size).toFixed(1)} ${unit}`

  return `${bytes} B`
}

/**
 * The absolute paths a cleanup deletes, each under `root`; throws, deleting
 * nothing, when one would reach outside it (an absolute part, `.` or `..`).
 */
export function cleanupTargets(root: string, relatives: readonly string[]): string[] {
  return relatives.map(relative => {
    const parts = relative.split(/[\\/]/)
    if (relative === '' || relative.startsWith('/') || /^[A-Za-z]:/.test(relative) || parts.some(part => part === '' || part === '.' || part === '..')) {
      throw new Error(`refused to delete outside ${root}: ${relative}`)
    }

    return `${root}/${relative}`
  })
}

files.hooks/usage.ts:
import type { RankRow, Tokens, UsageSummary } from '../types'

/**
 * Token usage counted from Claude Code's session transcripts on this machine.
 *
 * Each response the model sent is one transcript line with its usage. The
 * lines are read outside the plugin's environment (`sh`, `head`, `tail`,
 * `awk`), only the bytes appended since the last count, and only the fields
 * counted here leave the shell. A response is written once per content
 * block, so its message id is counted once.
 */


/** One response as the scan reads it. */
export type ScanRecord = { at: string; cwd: string; model: string; id: string; input: number; cacheWrite: number; cacheRead: number; output: number }

/** What has been counted, kept in a file of the mod's own between sessions. */
export type UsageIndex = {
  version: 3
  /** Per transcript: the bytes counted so far. */
  files: Record<string, { offset: number }>
  /**
   * Every message id counted, in any transcript: a resumed or forked session
   * copies earlier responses into its own transcript, ids and all, and each is
   * counted once. Kept as a list in the file; a count works on it as a set.
   */
  ids: string[]
  /** Tokens by `day\tmodel\tproject`; the day is the local date. */
  buckets: Record<string, Tokens>
  /**
   * Per session (its transcript's name; a subagent's transcript counts toward
   * the session that started it): the projects it worked in, the days it was
   * active and the models it used.
   */
  sessions: Record<string, { projects: string[]; days: string[]; models: string[] }>
}


export function emptyIndex(): UsageIndex {
  return { version: 3, files: {}, buckets: {}, sessions: {}, ids: [] }
}

/**
 * The session a transcript belongs to: its own name for a session's
 * transcript (`<project>/<session>.jsonl`), the folder it sits under for a
 * subagent's (`<project>/<session>/subagents/agent-<id>.jsonl`).
 */
export function sessionOf(relative: string): string {
  const parts = relative.split('/').filter(Boolean)
  if (parts.length >= 3) return parts[1] ?? ''

  return (parts[parts.length - 1] ?? '').replace(/\.jsonl$/, '')
}

/** Reads a stored index; anything else, an index of another version included, starts over. */
export function asIndex(value: unknown): UsageIndex {
  const index = value as Partial<UsageIndex> | null
  if (!index || index.version !== 3 || typeof index.files !== 'object' || typeof index.buckets !== 'object' || typeof index.sessions !== 'object' || !Array.isArray(index.ids)) {
    return emptyIndex()
  }

  return index as UsageIndex
}

/**
 * The scan: bytes `$3`.. `$2` of transcript `$1` (`$4` of them), each
 * assistant line with a usage reduced to tab-separated fields: time, working
 * directory, model, message id, then input, cache write, cache read and
 * output tokens. Every field is the first of its key, and the token keys are
 * looked for only in the usage object, whose keys come in no fixed order. A
 * line is printed once the next one starts or the bytes end on its newline,
 * so a line cut by the end of the range is left for the next scan; the last
 * line printed, `#` and a count, is how many bytes the complete lines took.
 */
export const SCAN_SCRIPT = [
  'head -c "$2" "$1" | tail -c +"$3" | LC_ALL=C awk -v size="$4" \'',
  'function str(key, text) { if (match(text, "\\"" key "\\":\\"[^\\"]*\\"")) return substr(text, RSTART + length(key) + 4, RLENGTH - length(key) - 5); return "" }',
  'function num(key, text) { if (match(text, "\\"" key "\\":[0-9]+")) return substr(text, RSTART + length(key) + 3, RLENGTH - length(key) - 3); return 0 }',
  '{',
  '  if (pending != "") print pending',
  '  pending = ""; last = length($0) + 1; total += last',
  '  if (index($0, "\\"type\\":\\"assistant\\"") && (u = index($0, "\\"usage\\":{\\""))) {',
  '    s = substr($0, u, 600)',
  '    pending = str("timestamp", $0) "\\t" str("cwd", $0) "\\t" str("model", $0) "\\t" str("id", $0) "\\t" num("input_tokens", s) "\\t" num("cache_creation_input_tokens", s) "\\t" num("cache_read_input_tokens", s) "\\t" num("output_tokens", s)',
  '  }',
  '}',
  'END { if (total <= size) { if (pending != "") print pending; print "#\\t" total } else print "#\\t" (total - last) }\'',
].join('\n')

/** How many bytes of the range the scan counted: up to the end of its last complete line. */
export function scannedBytes(stdout: string): number {
  const line = stdout.trimEnd().split('\n').pop() ?? ''

  return line.startsWith('#\t') ? Number(line.slice(2)) : 0
}

/** The scan's lines as records; a line without a message id or a time is left out. */
export function parseScan(stdout: string): ScanRecord[] {
  return stdout
    .split('\n')
    .map(line => line.split('\t'))
    .filter(parts => parts.length === 8 && parts[0] !== '' && (parts[3] ?? '').startsWith('msg_'))
    .map(([at = '', cwd = '', model = '', id = '', input = '0', cacheWrite = '0', cacheRead = '0', output = '0']) => ({
      at,
      cwd: cwd.replace(/\\\\/g, '\\'),
      model,
      id,
      input: Number(input),
      cacheWrite: Number(cacheWrite),
      cacheRead: Number(cacheRead),
      output: Number(output),
    }))
}

/** The local date of an ISO time, `YYYY-MM-DD`, by the offset the environment answers for that instant. */
export function localDay(iso: string, offsetMinutes?: number): string {
  const at = Date.parse(iso)
  const local = new Date(at - (offsetMinutes ?? new Date(at).getTimezoneOffset()) * 60_000)

  return local.toISOString().slice(0, 10)
}

/** A project's name: the last folder of the directory a session worked in. */
export function projectOf(cwd: string): string {
  const parts = cwd.split(/[\\/]/).filter(Boolean)

  return parts[parts.length - 1] ?? cwd
}

function addTokens(into: Tokens | undefined, record: Pick<ScanRecord, 'input' | 'output' | 'cacheRead' | 'cacheWrite'>): Tokens {
  const base = into ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, responses: 0 }

  return {
    input: base.input + record.input,
    output: base.output + record.output,
    cacheRead: base.cacheRead + record.cacheRead,
    cacheWrite: base.cacheWrite + record.cacheWrite,
    responses: base.responses + 1,
  }
}

/**
 * Adds one transcript's newly read records to the index, each message id
 * once across every transcript, and moves its offset to `offset`. `seen` is
 * the set of ids counted, which this adds to; the index passed in is not
 * changed, and the one returned leaves its `ids` to be written from `seen`.
 */
export function addRecords(
  index: UsageIndex,
  seen: Set<string>,
  file: string,
  session: string,
  records: ScanRecord[],
  offset: number,
  offsetMinutes?: number,
): UsageIndex {
  const buckets = { ...index.buckets }
  const sessions = { ...index.sessions }
  for (const record of records) {
    if (seen.has(record.id)) continue
    seen.add(record.id)
    const day = localDay(record.at, offsetMinutes)
    const project = projectOf(record.cwd)
    const key = `${day}\t${record.model}\t${project}`
    buckets[key] = addTokens(buckets[key], record)
    const known = sessions[session] ?? { projects: [], days: [], models: [] }
    sessions[session] = {
      projects: known.projects.includes(project) ? known.projects : [...known.projects, project],
      days: known.days.includes(day) ? known.days : [...known.days, day],
      models: known.models.includes(record.model) ? known.models : [...known.models, record.model],
    }
  }

  return { ...index, buckets, sessions, files: { ...index.files, [file]: { offset } } }
}


/** All four kinds of tokens together. */
export function totalOf(tokens: Tokens): number {
  return tokens.input + tokens.output + tokens.cacheRead + tokens.cacheWrite
}

/** Cache reads over the input the model read: input plus cache reads. Null with neither. */
export function cacheReuse(tokens: Tokens): number | null {
  const read = tokens.input + tokens.cacheRead

  return read === 0 ? null : tokens.cacheRead / read
}

/** The day `count - 1` days before `today`, `YYYY-MM-DD`. */
function daysBack(today: string, count: number): string {
  return new Date(Date.parse(`${today}T00:00:00Z`) - (count - 1) * 86_400_000).toISOString().slice(0, 10)
}

/**
 * The index summed over the last `days` days up to `today`, or over all of it
 * when `days` is null; rankings keep the `top` largest.
 */
export function summarize(index: UsageIndex, days: number | null, today: string, top = 5): UsageSummary {
  const days_ = Object.keys(index.buckets).map(key => key.split('\t')[0] ?? '')
  const first = days === null ? (days_.sort()[0] ?? today) : daysBack(today, days)
  const zero = (): Tokens => ({ input: 0, output: 0, cacheRead: 0, cacheWrite: 0, responses: 0 })
  const add = (a: Tokens, b: Tokens): Tokens => ({
    input: a.input + b.input,
    output: a.output + b.output,
    cacheRead: a.cacheRead + b.cacheRead,
    cacheWrite: a.cacheWrite + b.cacheWrite,
    responses: a.responses + b.responses,
  })
  let totals = zero()
  const byDay = new Map<string, Tokens>()
  const byModel = new Map<string, Tokens>()
  const byProject = new Map<string, Tokens>()
  for (const [key, tokens] of Object.entries(index.buckets)) {
    const [day = '', model = '', project = ''] = key.split('\t')
    if (day < first || day > today) continue
    totals = add(totals, tokens)
    byDay.set(day, add(byDay.get(day) ?? zero(), tokens))
    byModel.set(model, add(byModel.get(model) ?? zero(), tokens))
    byProject.set(project, add(byProject.get(project) ?? zero(), tokens))
  }
  const active = Object.values(index.sessions).filter(session => session.days.some(day => day >= first && day <= today))
  const rank = (map: Map<string, Tokens>, sessionsOf: (name: string) => number): RankRow[] =>
    [...map.entries()]
      .map(([name, tokens]) => ({ name, tokens, sessions: sessionsOf(name) }))
      .sort((a, b) => totalOf(b.tokens) - totalOf(a.tokens))
      .slice(0, top)
  const daily: UsageSummary['daily'] = []
  for (let at = Date.parse(`${first}T00:00:00Z`); at <= Date.parse(`${today}T00:00:00Z`); at += 86_400_000) {
    const day = new Date(at).toISOString().slice(0, 10)
    daily.push({ day, tokens: byDay.get(day) ?? zero() })
  }

  return {
    totals,
    daily,
    models: rank(byModel, name => active.filter(session => session.models.includes(name)).length),
    projects: rank(byProject, name => active.filter(session => session.projects.includes(name)).length),
    sessions: active.length,
  }
}

/** A token count in a few characters: `873`, `12.4k`, `221.6M`, `1.9B`. */
export function compactCount(value: number): string {
  if (value < 1000) return String(value)
  const units: [number, string][] = [
    [1e9, 'B'],
    [1e6, 'M'],
    [1e3, 'k'],
  ]
  for (const [size, unit] of units) if (value >= size) return `${(value / size).toFixed(1)}${unit}`

  return String(value)
}

/** Message ids written to one file: well under the engine's 4 MiB a read or a write takes. */
export const IDS_PER_FILE = 80_000

/**
 * The index as written: its ids in files of their own, `IDS_PER_FILE` to a
 * file, and the index naming how many there are; the engine reads and writes
 * at most 4 MiB at a time, and a machine's ids pass that.
 */
export function indexToStore(index: UsageIndex, ids: readonly string[]): { index: UsageIndex & { idFiles: number }; idFiles: string[][] } {
  const idFiles: string[][] = []
  for (let start = 0; start < ids.length; start += IDS_PER_FILE) idFiles.push(ids.slice(start, start + IDS_PER_FILE))

  return { index: { ...index, ids: [], idFiles: idFiles.length }, idFiles }
}

files.hooks/platform.ts:
import { removeArgv } from './shared/files'

/**
 * Where Claude Code keeps its login on this machine. macOS keeps it in the
 * keychain; Linux, WSL and Windows keep it in `<config dir>/.credentials.json`.
 */
export type Backend = 'keychain' | 'file'

export type Platform = {
  backend: Backend
  /** Windows proper (not WSL): no POSIX shell, `cmd.exe` deletes files. */
  isWindows: boolean
}

/**
 * @param osVariable the `OS` environment variable, `Windows_NT` on Windows
 * @param kernelName `uname -s` output, or undefined where `uname` did not run
 */
export function detectPlatform(osVariable: string | undefined, kernelName: string | undefined): Platform {
  if (osVariable === 'Windows_NT') return { backend: 'file', isWindows: true }
  if (kernelName === undefined) return { backend: 'file', isWindows: false }

  return { backend: kernelName.trim() === 'Darwin' ? 'keychain' : 'file', isWindows: false }
}

/** The vault file of one saved account under the file backend. */
export function vaultFilePath(claudeDirectory: string, vaultName: string, account: string): string {
  if (!/^[A-Za-z0-9_-]+$/.test(account)) throw new Error(`unsafe account id: ${account}`)

  return `${claudeDirectory}/${vaultName}/${account}.json`
}

/**
 * argv writing stdin to `path` with owner-only permissions, on a POSIX shell.
 * The umask covers a new file and folder; a file already there keeps its mode
 * through `cat >`, so it is narrowed to 600 before the secret goes in.
 */
export function privateWriteArgv(path: string): string[] {
  return ['/bin/sh', '-c', 'umask 077 && mkdir -p "$(dirname "$0")" && touch "$0" && chmod 600 "$0" && cat > "$0"', path]
}

/** argv deleting `path`, absent or not. */
export function deleteFileArgv(path: string, isWindows: boolean): string[] {
  return removeArgv([path], isWindows)
}

